export function defineServerPlugin(definition) {
    const packageName = normalizePackageName(definition.packageName);
    if (typeof definition.baseDir !== 'string' ||
        !path.isAbsolute(definition.baseDir)) {
        throw new Error(`Server plugin "${packageName}" requires an absolute baseDir. Set baseDir relative to the declaring module with import.meta.dirname.`);
